using System.IO;
using System.Text.Json;
using Orbit.Core;
namespace OrbitLauncher;
public partial class MainWindow {
 async Task CheckQuickLoaderUiAsync(string root){var report=new List<string>();void Check(bool ok,string title){if(!ok)throw new Exception(title);report.Add("PASS "+title);}async Task<JsonElement> Js(string js)=>JsonDocument.Parse(await brawlBrowser!.CoreWebView2.ExecuteScriptAsync(js)).RootElement.Clone();
 try{NicknameBox.Text="Player";settings.Theme="brawl stars";ApplyTheme();Navigate("Home");await brawlInitTask;await brawlPageReady.Task.WaitAsync(TimeSpan.FromSeconds(35));await LoadCatalogAsync();selectedChoice=new VersionEntry("1.12.2","Vanilla","1.12.2",8);SyncBrawlState();await Task.Delay(1200);
 foreach(string loader in new[]{"Fabric","Forge"}){await Js("document.querySelector('.lobby-mode').click()");await Task.Delay(250);await Js("document.querySelector('.orbit-quick-actions ."+loader.ToLowerInvariant()+"').click()");await Task.Delay(150);Check((await Js("!!document.querySelector('[aria-label=\"Quick loader\"]')")).GetBoolean(),loader+" dialog opens");for(int i=0;i<200&&(quickCatalogLoading||quickCatalogLoader!=loader);i++)await Task.Delay(100);SyncBrawlState();await Task.Delay(400);Check(quickCatalogError==""&&!quickCatalogLoading,loader+" supported catalog loaded");var state=await Js("(()=>{const d=document.querySelector('[aria-label=\"Quick loader\"]'),s=d.querySelector('select');return {options:[...s.options].map(o=>o.value),selected:s.value,enabled:!d.querySelector('button.primary').disabled}})()");var options=state.GetProperty("options").EnumerateArray().Select(x=>x.GetString()).ToArray();Check(options.Contains("1.21.1")&&options.Length>0,loader+" offers supported Minecraft releases");if(loader=="Fabric")Check(!options.Contains("1.12.2")&&state.GetProperty("selected").GetString()!="1.12.2","Fabric never offers unsupported 1.12.2 and selects a valid replacement");else Check(options.Contains("1.12.2"),"Forge retains supported legacy 1.12.2");Check(state.GetProperty("enabled").GetBoolean(),loader+" install enabled only after compatible selection");using(var image=File.Create(Path.Combine(root,"quick-"+loader.ToLowerInvariant()+"-fixed.png")))await brawlBrowser!.CoreWebView2.CapturePreviewAsync(Microsoft.Web.WebView2.Core.CoreWebView2CapturePreviewImageFormat.Png,image);await Js("document.querySelector('.orbit-close').click()");await Task.Delay(250);}
 await Js("document.querySelector('.lobby-mode').click()");await Task.Delay(350);Check((await Js("document.querySelectorAll('.orbit-version-tabs [role=tab]').length===3")).GetBoolean(),"Version picker has All versions, Forge and Fabric tabs");
 foreach(string loader in new[]{"Fabric","Forge"}){await Js("[...document.querySelectorAll('.orbit-version-tabs [role=tab]')].find(b=>b.textContent==='"+loader+"').click()");await Task.Delay(200);for(int i=0;i<200&&quickCatalogLoading;i++)await Task.Delay(100);SyncBrawlState();await Task.Delay(450);Check((await Js("document.querySelectorAll('.orbit-version-list .orbit-version').length>0&&[...document.querySelectorAll('.orbit-version-list .orbit-version')].every(b=>b.classList.contains('"+loader.ToLowerInvariant()+"'))")).GetBoolean(),loader+" tab renders only its loader rows");if(loader=="Fabric")Check((await Js("![...document.querySelectorAll('.orbit-version-list .orbit-version')].some(b=>b.textContent.includes('1.12.2'))")).GetBoolean(),"Fabric tab excludes Minecraft 1.12.2");}
 Width=900;Height=680;await Task.Delay(600);Check((await Js("(()=>{const r=document.querySelector('.orbit-version-picker').getBoundingClientRect();return r.top>=0&&r.right<=innerWidth&&r.bottom<=innerHeight})()")).GetBoolean(),"Version tabs fit minimum window size");Check((await Js("(()=>{const b=document.querySelector('.orbit-version-picker .orbit-toolbar button'),r=b.getBoundingClientRect();return b.contains(document.elementFromPoint(r.left+r.width/2,r.top+r.height/2))})()")).GetBoolean(),"Picker close button is above header controls at minimum size");using(var image=File.Create(Path.Combine(root,"version-tabs-default.png")))await brawlBrowser!.CoreWebView2.CapturePreviewAsync(Microsoft.Web.WebView2.Core.CoreWebView2CapturePreviewImageFormat.Png,image);
 settings.Theme="default";ApplyTheme();foreach(string loader in new[]{"Forge","Fabric"}){pickerMode=loader;ApplyPickerFilter();Check(VersionCombo.Visibility==System.Windows.Visibility.Collapsed&&LoaderVersionList.Visibility==System.Windows.Visibility.Visible&&LoaderVersionList.Items.Count>0,loader+" native tab uses compatible loader list");Check(LoaderVersionList.Items.OfType<VersionEntry>().All(v=>v.Loader==loader),loader+" native tab never labels vanilla as an installed loader");PickerSearch.Text="1.21.1";Check(LoaderVersionList.Items.OfType<VersionEntry>().All(v=>v.BaseVersion.Contains("1.21.1")),loader+" native tab search filters Minecraft versions");PickerSearch.Text="";}pickerMode="All";ApplyPickerFilter();Check(VersionCombo.Visibility==System.Windows.Visibility.Visible&&LoaderVersionList.Visibility==System.Windows.Visibility.Collapsed,"Native All versions restores normal version selection");
 Check((await Js("window.orbitErrors.length===0")).GetBoolean(),"No React errors after loader catalog updates");
 }finally{File.WriteAllLines(Path.Combine(root,"quick-loader-ui-checks.txt"),report);}
 }
